export class RelatedPlaceGraph {#edges=[];add(input={}){if(!input.from||!input.to||!input.sourceId)return{accepted:false,reason:'OFFICIAL_OR_LICENSED_SOURCE_REQUIRED'};if(input.from===input.to)return{accepted:false,reason:'SELF_EDGE'};const edge=Object.freeze({from:String(input.from),to:String(input.to),relationType:input.relationType||'RELATED',weight:Number.isFinite(input.weight)?input.weight:null,sourceId:String(input.sourceId),sourceSemantics:input.sourceSemantics||'PROVIDER_RELATIONSHIP'});if(!this.#edges.some(e=>e.from===edge.from&&e.to===edge.to&&e.sourceId===edge.sourceId))this.#edges.push(edge);return{accepted:true,edge};}neighbors(id){return this.#edges.filter(e=>e.from===id||e.to===id).map(structuredClone);}snapshot(){return this.#edges.map(structuredClone);}}
